const TRACKED_CHANGE_GUTTER_WIDTH_PX = 300;
const TRACKED_CHANGE_GUTTER_CARD_LEFT_PX = 12;
const TRACKED_CHANGE_GUTTER_CARD_RIGHT_PX = 12;
const TRACKED_CHANGE_GUTTER_CARD_GAP_PX = 4;
const TRACKED_CHANGE_GUTTER_CARD_MIN_HEIGHT_PX = 30;
const TRACKED_CHANGE_GUTTER_CONNECTOR_LANE_COUNT = 5;

function scheduleDomWrite(callback: () => void): void {
  if (
    typeof window !== "undefined" &&
    typeof window.requestAnimationFrame === "function"
  ) {
    window.requestAnimationFrame(() => {
      callback();
    });
    return;
  }

  setTimeout(callback, 0);
}

function normalizeMeasuredTableRowHeightPx(heightPx: number): number {
  if (!Number.isFinite(heightPx) || heightPx <= 0) {
    return MIN_PARAGRAPH_LINE_HEIGHT_PX;
  }

  return Math.max(MIN_PARAGRAPH_LINE_HEIGHT_PX, Math.round(heightPx));
}

function normalizeMeasuredTableRowHeightForDefinitionPx(
  heightPx: number,
  table: TableNode,
  rowIndex: number
): number {
  const measuredHeight = normalizeMeasuredTableRowHeightPx(heightPx);
  const row = table.rows[rowIndex];
  if (!row) return measuredHeight;
  if (tableAutomaticCollapsedBorderWidthPx(table) > 0 &&
    Number.isFinite(heightPx) && heightPx > 0) {
    return Math.max(MIN_PARAGRAPH_LINE_HEIGHT_PX, heightPx);
  }
  const declaredHeight = tableRowHeightFromDefinitionPx(table, row, rowIndex);
  if (declaredHeight === undefined) return measuredHeight;
  if (row.style?.heightRule === "exact" && measuredHeight === Math.round(declaredHeight)) {
    return Math.max(MIN_PARAGRAPH_LINE_HEIGHT_PX, declaredHeight);
  }
  return Math.max(measuredHeight, declaredHeight);
}

function reconcileMeasuredTableRowHeightsForImportPagination(
  table: TableNode,
  measuredRowHeights: number[],
  maxAvailableWidthPx?: number,
  pageContentHeightPx?: number,
  numberingDefinitions?: NumberingDefinitionSet,
  docGridLinePitchPx?: number,
  percentageReferenceWidthPx = maxAvailableWidthPx,
  typography?: DocxTypographyOptions
): number[] | undefined {
  if (measuredRowHeights.length !== table.rows.length) {
    return undefined;
  }

  const estimatedRowHeights = estimateTableRowHeightsPx(
    table,
    maxAvailableWidthPx,
    numberingDefinitions,
    docGridLinePitchPx,
    pageContentHeightPx,
    percentageReferenceWidthPx, typography
  );
  if (estimatedRowHeights.length !== table.rows.length) {
    return undefined;
  }

  return measuredRowHeights.map((heightPx, rowIndex) => {
    const row = table.rows[rowIndex];
    const normalizedMeasuredHeightPx =
      normalizeMeasuredTableRowHeightForDefinitionPx(heightPx, table, rowIndex);
    const normalizedPageContentHeightPx =
      Number.isFinite(pageContentHeightPx) &&
      (pageContentHeightPx as number) > 0
        ? Math.max(120, Math.round(pageContentHeightPx as number))
        : undefined;
    const estimatedHeightPx = Math.max(
      MIN_PARAGRAPH_LINE_HEIGHT_PX,
      row.style?.heightRule === "exact" || tableAutomaticCollapsedBorderWidthPx(table) > 0
        ? estimatedRowHeights[rowIndex] ?? MIN_PARAGRAPH_LINE_HEIGHT_PX
        : Math.round(estimatedRowHeights[rowIndex] ?? MIN_PARAGRAPH_LINE_HEIGHT_PX)
    );
    const explicitHeightPx = tableRowHeightFromDefinitionPx(table, row, rowIndex);
    const normalizedExplicitHeightPx =
      Number.isFinite(explicitHeightPx) && (explicitHeightPx as number) > 0
        ? Math.max(
            MIN_PARAGRAPH_LINE_HEIGHT_PX,
            explicitHeightPx as number
          )
        : undefined;
    const allowedGrowthPx = rowHasDeepFlowContent(row)
      ? Math.max(
          MIN_PARAGRAPH_LINE_HEIGHT_PX,
          Math.round(estimatedHeightPx * 0.2)
        )
      : Math.max(4, Math.round(MIN_PARAGRAPH_LINE_HEIGHT_PX * 0.5));
    const explicitMinimumHeightPx =
      normalizedExplicitHeightPx ?? MIN_PARAGRAPH_LINE_HEIGHT_PX;
    if (rowAllowsPageSplit(row) && row.style?.heightRule !== "exact") {
      return Math.max(explicitMinimumHeightPx, normalizedMeasuredHeightPx);
    }

    if (
      Number.isFinite(normalizedPageContentHeightPx) &&
      normalizedMeasuredHeightPx >
        (normalizedPageContentHeightPx as number) + PAGE_OVERFLOW_TOLERANCE_PX
    ) {
      return Math.max(explicitMinimumHeightPx, normalizedMeasuredHeightPx);
    }

    const minimumHeightPx = Math.max(
      estimatedHeightPx,
      explicitMinimumHeightPx
    );
    const maximumHeightPx = Math.max(
      minimumHeightPx,
      (normalizedExplicitHeightPx ?? estimatedHeightPx) + allowedGrowthPx
    );
    return clampNumber(
      normalizedMeasuredHeightPx,
      minimumHeightPx,
      maximumHeightPx
    );
  });
}

export interface MeasuredTableRowHeightsEntry {
  rowHeightsPx: number[];
  contentSignature: string;
}

export function resolveTableMeasuredRowHeightsForPagination(
  nodes: DocModel["nodes"],
  tableMeasuredRowHeightsByBlockId: Record<
    string,
    MeasuredTableRowHeightsEntry
  >,
  options?: {
    allowMeasuredImportPagination?: boolean;
    allowContentSignatureValidatedTables?: boolean;
    activeDraftKeys?: string[];
    numberingDefinitions?: NumberingDefinitionSet;
    pageContentWidthPxByNodeIndex?: Map<number, number | undefined>;
    pageTextWidthPxByNodeIndex?: Map<number, number | undefined>;
    pageContentHeightPxByNodeIndex?: Map<number, number | undefined>;
    docGridLinePitchPxByNodeIndex?: Map<number, number | undefined>;
  },
  typography?: DocxTypographyOptions
): Record<number, number[]> | undefined {
  const activeTableIndexes = new Set<number>();

  (options?.activeDraftKeys ?? []).forEach((draftKey) => {
    const [tableIndexText] = draftKey.split(":");
    const tableIndex = Number.parseInt(tableIndexText ?? "", 10);
    if (Number.isFinite(tableIndex) && tableIndex >= 0) {
      activeTableIndexes.add(tableIndex);
    }
  });

  const includeOnlyActiveTables = activeTableIndexes.size > 0;
  if (
    includeOnlyActiveTables === false &&
    options?.allowMeasuredImportPagination !== true &&
    options?.allowContentSignatureValidatedTables !== true
  ) {
    return undefined;
  }

  const next: Record<number, number[]> = {};
  nodes.forEach((tableNode, tableIndex) => {
    if (tableNode.type !== "table" || !tableNode.blockId) {
      return;
    }

    const entry = tableMeasuredRowHeightsByBlockId[tableNode.blockId];
    if (
      !entry ||
      !Array.isArray(entry.rowHeightsPx) ||
      entry.rowHeightsPx.length !== tableNode.rows.length
    ) {
      return;
    }
    const measuredRowHeights = entry.rowHeightsPx;

    if (includeOnlyActiveTables) {
      if (!activeTableIndexes.has(tableIndex)) {
        return;
      }
      next[tableIndex] = measuredRowHeights.map((heightPx, rowIndex) =>
        normalizeMeasuredTableRowHeightForDefinitionPx(heightPx, tableNode, rowIndex)
      );
      return;
    }

    // Post-edit, a table's measured heights stay usable only while its
    // content is unchanged since measurement (the import path skips this:
    // nothing can have changed on a pristine document).
    if (
      options?.allowMeasuredImportPagination !== true &&
      entry.contentSignature !== docNodeContentSignature(tableNode)
    ) {
      return;
    }

    next[tableIndex] =
      reconcileMeasuredTableRowHeightsForImportPagination(
        tableNode,
        measuredRowHeights,
        options?.pageContentWidthPxByNodeIndex?.get(tableIndex),
        options?.pageContentHeightPxByNodeIndex?.get(tableIndex),
        options?.numberingDefinitions,
        options?.docGridLinePitchPxByNodeIndex?.get(tableIndex),
        options?.pageTextWidthPxByNodeIndex?.get(tableIndex), typography
      ) ??
      measuredRowHeights.map((heightPx) =>
        normalizeMeasuredTableRowHeightPx(heightPx)
      );
  });

  return Object.keys(next).length > 0 ? next : undefined;
}

export interface MeasuredPageContentValidation {
  contextSignature: string;
  blocks: Array<{ blockId?: string; contentSignature: string }>;
}

export function buildMeasuredPageContentValidationForPageSegments(
  pageSegments: DocumentPageNodeSegment[],
  nodes: DocModel["nodes"],
  contextSignature: string
): MeasuredPageContentValidation {
  const blocks: MeasuredPageContentValidation["blocks"] = [];
  let previousNodeIndex: number | undefined;
  for (const segment of pageSegments) {
    if (segment.nodeIndex === previousNodeIndex) {
      continue;
    }
    previousNodeIndex = segment.nodeIndex;
    const node = nodes[segment.nodeIndex];
    blocks.push({
      blockId: node?.blockId,
      contentSignature: node ? docNodeContentSignature(node) : "",
    });
  }
  return { contextSignature, blocks };
}

export function measuredPageContentValidationsEqual(
  left: MeasuredPageContentValidation | undefined,
  right: MeasuredPageContentValidation | undefined
): boolean {
  if (left === right) {
    return true;
  }
  if (!left || !right) {
    return false;
  }
  if (
    left.contextSignature !== right.contextSignature ||
    left.blocks.length !== right.blocks.length
  ) {
    return false;
  }
  for (let index = 0; index < left.blocks.length; index += 1) {
    if (
      left.blocks[index].blockId !== right.blocks[index].blockId ||
      left.blocks[index].contentSignature !==
        right.blocks[index].contentSignature
    ) {
      return false;
    }
  }
  return true;
}

/**
 * Measured page-content heights are keyed by page index, so a per-block
 * signature check alone cannot validate them: page N's measurement holds only
 * while the page still receives the same blocks with the same content, which
 * is guaranteed only when every block on pages 0..N is unchanged. Walks pages
 * in order against the current body nodes and keeps the clean prefix.
 */
export function resolveMeasuredPageContentHeightsPxForEditedModel(
  nodes: DocModel["nodes"],
  measuredPageContentHeightsPxByPageIndex: number[],
  validationByPageIndex: Array<MeasuredPageContentValidation | undefined>,
  contextSignature: string
): number[] | undefined {
  let cursor = 0;
  let previousPageLastBlockId: string | undefined;
  let validPageCount = 0;

  for (
    let pageIndex = 0;
    pageIndex < measuredPageContentHeightsPxByPageIndex.length;
    pageIndex += 1
  ) {
    const validation = validationByPageIndex[pageIndex];
    if (
      !validation ||
      validation.contextSignature !== contextSignature ||
      validation.blocks.length === 0
    ) {
      break;
    }

    let pageIsValid = true;
    for (
      let blockIndex = 0;
      blockIndex < validation.blocks.length;
      blockIndex += 1
    ) {
      const block = validation.blocks[blockIndex];
      if (!block.blockId) {
        pageIsValid = false;
        break;
      }
      if (blockIndex === 0 && block.blockId === previousPageLastBlockId) {
        // Continuation of the block that ended the previous page; it was
        // already matched against the cursor there.
        continue;
      }
      const node = nodes[cursor];
      if (
        !node ||
        node.blockId !== block.blockId ||
        docNodeContentSignature(node) !== block.contentSignature
      ) {
        pageIsValid = false;
        break;
      }
      cursor += 1;
    }

    if (!pageIsValid) {
      break;
    }

    previousPageLastBlockId =
      validation.blocks[validation.blocks.length - 1]?.blockId;
    validPageCount += 1;
  }

  if (validPageCount === 0) {
    return undefined;
  }

  return validPageCount >= measuredPageContentHeightsPxByPageIndex.length
    ? measuredPageContentHeightsPxByPageIndex
    : measuredPageContentHeightsPxByPageIndex.slice(0, validPageCount);
}

function placeCaretInsideElementDom(element: HTMLElement): void {
  const selection = window.getSelection();
  if (!selection) {
    return;
  }

  const range = document.createRange();
  range.selectNodeContents(element);
  range.collapse(false);
  selection.removeAllRanges();
  selection.addRange(range);
}

function selectionOffsetsWithinElementDom(
  element: HTMLElement
): { start: number; end: number } | undefined {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) {
    return undefined;
  }

  const selectedRange = selection.getRangeAt(0);
  if (
    !element.contains(selectedRange.startContainer) ||
    !element.contains(selectedRange.endContainer)
  ) {
    return undefined;
  }

  try {
    const textLengthWithoutNumberingLabels = (range: Range): number => {
      const fragment = range.cloneContents();
      fragment
        .querySelectorAll("[data-docx-numbering-label='true'],[data-docx-image-location]")
        .forEach((label) => {
          label.remove();
        });
      return fragment.textContent?.length ?? 0;
    };

    const startRange = document.createRange();
    startRange.setStart(element, 0);
    startRange.setEnd(selectedRange.startContainer, selectedRange.startOffset);

    const endRange = document.createRange();
    endRange.setStart(element, 0);
    endRange.setEnd(selectedRange.endContainer, selectedRange.endOffset);

    const startOffset = textLengthWithoutNumberingLabels(startRange);
    const endOffset = textLengthWithoutNumberingLabels(endRange);

    return {
      start: Math.min(startOffset, endOffset),
      end: Math.max(startOffset, endOffset),
    };
  } catch {
    return undefined;
  }
}

function staticRangeOffsetsWithinElementDom(
  element: HTMLElement,
  staticRange: {
    startContainer: Node;
    startOffset: number;
    endContainer: Node;
    endOffset: number;
  }
): { start: number; end: number } | undefined {
  if (
    !element.contains(staticRange.startContainer) ||
    !element.contains(staticRange.endContainer)
  ) {
    return undefined;
  }

  try {
    const textLengthWithoutNumberingLabels = (range: Range): number => {
      const fragment = range.cloneContents();
      fragment
        .querySelectorAll("[data-docx-numbering-label='true'],[data-docx-image-location]")
        .forEach((label) => {
          label.remove();
        });
      return fragment.textContent?.length ?? 0;
    };

    const startRange = document.createRange();
    startRange.setStart(element, 0);
    startRange.setEnd(staticRange.startContainer, staticRange.startOffset);

    const endRange = document.createRange();
    endRange.setStart(element, 0);
    endRange.setEnd(staticRange.endContainer, staticRange.endOffset);

    const startOffset = textLengthWithoutNumberingLabels(startRange);
    const endOffset = textLengthWithoutNumberingLabels(endRange);

    return {
      start: Math.min(startOffset, endOffset),
      end: Math.max(startOffset, endOffset),
    };
  } catch {
    return undefined;
  }
}

function setSelectionWithinElementByTextOffsetsDom(
  element: HTMLElement,
  startOffset: number,
  endOffset: number
): void {
  const selection = window.getSelection();
  if (!selection) {
    return;
  }

  const resolveDomPosition = (
    container: HTMLElement,
    targetOffset: number
  ): {
    node: Node;
    offset: number;
  } => {
    const safeOffset = Math.max(0, Math.round(targetOffset));
    const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
    let traversed = 0;
    let currentTextNode: Node | null = walker.nextNode();

    while (currentTextNode) {
      if (
        currentTextNode instanceof Text &&
        currentTextNode.parentElement?.closest(
          "[data-docx-numbering-label='true'],[data-docx-image-location]"
        )
      ) {
        currentTextNode = walker.nextNode();
        continue;
      }

      const textLength = currentTextNode.textContent?.length ?? 0;
      if (traversed + textLength >= safeOffset) {
        return {
          node: currentTextNode,
          offset: Math.max(0, safeOffset - traversed),
        };
      }

      traversed += textLength;
      currentTextNode = walker.nextNode();
    }

    return {
      node: container,
      offset: container.childNodes.length,
    };
  };

  try {
    const range = document.createRange();
    const normalizedStart = Math.max(0, Math.min(startOffset, endOffset));
    const normalizedEnd = Math.max(
      normalizedStart,
      Math.max(startOffset, endOffset)
    );
    const start = resolveDomPosition(element, normalizedStart);
    const end = resolveDomPosition(element, normalizedEnd);
    range.setStart(start.node, start.offset);
    range.setEnd(end.node, end.offset);
    selection.removeAllRanges();
    selection.addRange(range);
  } catch {
    placeCaretInsideElementDom(element);
  }
}

