export function useDocxTrackChanges(
  editor: Pick<
    DocxEditorController,
    | "trackedChanges"
    | "showTrackedChanges"
    | "setShowTrackedChanges"
    | "toggleShowTrackedChanges"
    | "acceptTrackedChange"
    | "rejectTrackedChange"
  >
): UseDocxTrackChangesResult {
  const changesByLocation = React.useMemo(() => {
    const grouped = new Map<string, DocxTrackedChange[]>();
    editor.trackedChanges.forEach((change) => {
      const key = paragraphLocationKey(change.location);
      const bucket = grouped.get(key) ?? [];
      bucket.push(change);
      grouped.set(key, bucket);
    });
    return grouped;
  }, [editor.trackedChanges]);

  const getChangesForLocation = React.useCallback(
    (location: DocxTextRangeLocation): DocxTrackedChange[] => {
      return changesByLocation.get(paragraphLocationKey(location)) ?? [];
    },
    [changesByLocation]
  );

  return React.useMemo(
    () => ({
      trackedChanges: editor.trackedChanges,
      showTrackedChanges: editor.showTrackedChanges,
      setShowTrackedChanges: editor.setShowTrackedChanges,
      toggleShowTrackedChanges: editor.toggleShowTrackedChanges,
      changesByLocation,
      getChangesForLocation,
      acceptChange: editor.acceptTrackedChange,
      rejectChange: editor.rejectTrackedChange,
    }),
    [
      editor.trackedChanges,
      editor.showTrackedChanges,
      editor.setShowTrackedChanges,
      editor.toggleShowTrackedChanges,
      editor.acceptTrackedChange,
      editor.rejectTrackedChange,
      changesByLocation,
      getChangesForLocation,
    ]
  );
}

/**
 * Exposes document comments and the show/hide state, mirroring
 * `useDocxTrackChanges`. Pair with `DocxEditorViewer`'s `renderCommentCard`
 * to fully customize how comments render.
 */
export function useDocxComments(
  editor: Pick<
    DocxEditorController,
    | "comments"
    | "showComments"
    | "setShowComments"
    | "toggleShowComments"
    | "createComment"
    | "setCommentResolved"
  >
): UseDocxCommentsResult {
  const commentsByLocation = React.useMemo(() => {
    const grouped = new Map<string, DocxComment[]>();
    editor.comments.forEach((comment) => {
      const key = paragraphLocationKey(comment.location);
      const bucket = grouped.get(key) ?? [];
      bucket.push(comment);
      grouped.set(key, bucket);
    });
    return grouped;
  }, [editor.comments]);

  const getCommentsForLocation = React.useCallback(
    (location: DocxTextRangeLocation): DocxComment[] => {
      return commentsByLocation.get(paragraphLocationKey(location)) ?? [];
    },
    [commentsByLocation]
  );

  return React.useMemo(
    () => ({
      comments: editor.comments,
      showComments: editor.showComments,
      setShowComments: editor.setShowComments,
      toggleShowComments: editor.toggleShowComments,
      commentsByLocation,
      getCommentsForLocation,
      createComment: editor.createComment,
      setCommentResolved: editor.setCommentResolved,
    }),
    [
      editor.comments,
      editor.showComments,
      editor.setShowComments,
      editor.toggleShowComments,
      editor.createComment,
      editor.setCommentResolved,
      commentsByLocation,
      getCommentsForLocation,
    ]
  );
}

export function useDocxPageLayout(
  editor: Pick<DocxEditorController, "model">
): UseDocxPageLayoutResult {
  const primarySectionPropertiesXml =
    editor.model.metadata.sections?.[0]?.sectionPropertiesXml ??
    editor.model.metadata.sectionPropertiesXml;
  const documentLayoutFallback = resolveDocumentLayoutFallback(editor.model);
  const layout = React.useMemo<DocxPageLayoutInfo>(() => {
    const sectionLayout = parseSectionLayout(
      primarySectionPropertiesXml,
      documentLayoutFallback
    );
    const sectionColumns = parseSectionColumns(primarySectionPropertiesXml);
    const pageNumberStart = parseSectionPageNumberStart(
      primarySectionPropertiesXml
    );
    const contentWidthPx = Math.max(
      120,
      sectionLayout.pageWidthPx -
        sectionLayout.marginsPx.left -
        sectionLayout.marginsPx.right
    );
    const contentHeightPx = Math.max(
      120,
      sectionLayout.pageHeightPx -
        sectionLayout.marginsPx.top -
        sectionLayout.marginsPx.bottom
    );

    return {
      pageWidthPx: sectionLayout.pageWidthPx,
      pageHeightPx: sectionLayout.pageHeightPx,
      contentWidthPx,
      contentHeightPx,
      marginsPx: { ...sectionLayout.marginsPx },
      headerDistancePx: sectionLayout.headerDistancePx,
      footerDistancePx: sectionLayout.footerDistancePx,
      pageNumberStart,
      columns: sectionColumns
        ? {
            count: sectionColumns.count,
            gapPx: sectionColumns.gapPx,
          }
        : undefined,
      viewportDefaults: {
        zoomPercent: 100,
        pageGapPx: DOC_PAGE_BREAK_GAP,
      },
    };
  }, [primarySectionPropertiesXml, documentLayoutFallback]);

  return React.useMemo(
    () => ({
      layout,
    }),
    [layout]
  );
}

